const __aivicBundle_27_identifyUnreportedMembers = (() => {
  function identifyUnreportedMembers(params: {
    members: Array<{
      userId: string;
      name: string;
      departmentId: string;
      hasReported: boolean;
      reportedAt?: string;
    }>;
    meetingConfig: {
      meetingDate: string;
      meetingTimeUtc: string;
      reportDeadlineUtc: string;
    };
    currentTimeUtc: string;
  }): {
    unreportedCount: number;
    unreportedMembers: Array<{
      userId: string;
      name: string;
      departmentId: string;
      status: string;
      deadline: string;
    }>;
    isMonthEndDate: boolean;
    targetDate: string;
  } {
    if (params["currentTimeUtc"] === undefined || params["currentTimeUtc"] === null) { throw new Error("currentTimeUtc is required"); }
    const { members, meetingConfig } = params;
  
    // Extract target date from meetingConfig.meetingDate (YYYY-MM-DD format)
    const targetDate = meetingConfig.meetingDate;
  
    // Parse the date to check if it's the 31st (month end)
    const dateObj = new Date(targetDate);
    const dayOfMonth = dateObj.getUTCDate();
    const isMonthEndDate = dayOfMonth === 31;
  
    // Filter unreported members
    const unreportedMembers = members
      .filter((member) => !member.hasReported)
      .map((member) => ({
        userId: member.userId,
        name: member.name,
        departmentId: member.departmentId,
        status: "本日未報告",
        deadline: meetingConfig.reportDeadlineUtc,
      }));
  
    return {
      unreportedCount: unreportedMembers.length,
      unreportedMembers,
      isMonthEndDate,
      targetDate,
    };
  }
  return { identifyUnreportedMembers };
})();
