/* AIVIC_FUNCTION_BUNDLE_START owner=sendPromptNotificationEmailsForNonReporters exports=sendPromptNotificationEmailsForNonReporters */
const __aivicBundle_175_sendPromptNotificationEmailsForNonReporters = (() => {
  interface SendPromptNotificationEmailsForNonReportersInput {
    all_member_user_ids: string[];
    reported_user_ids: string[];
    non_reporter_email_address: string;
    notification_deadline_time: string;
    morning_meeting_start_time: string;
  }
  
  interface SendPromptNotificationEmailsForNonReportersOutput {
    prompt_target_user_count: number;
    prompt_target_user_ids: string[];
    notification_email_sent: boolean;
    notification_email_send_count: number;
  }
  
   async function sendPromptNotificationEmailsForNonReporters(
    input: SendPromptNotificationEmailsForNonReportersInput
  ): Promise<SendPromptNotificationEmailsForNonReportersOutput> {
    const {
      all_member_user_ids,
      reported_user_ids,
      non_reporter_email_address,
      notification_deadline_time,
      morning_meeting_start_time,
    } = input;
  
    // 未報告者を特定: 全メンバーから報告済みメンバーを除外
    const reportedSet = new Set(reported_user_ids);
    const nonReporterUserIds = all_member_user_ids.filter(
      (userId) => !reportedSet.has(userId)
    );
  
    const promptTargetCount = nonReporterUserIds.length;
  
    // 未報告者がいる場合、メール送信を実行
    let emailSent = false;
    let emailSendCount = 0;
  
    if (promptTargetCount > 0) {
      try {
        // 外部メールサービスへのリクエスト
        const emailPayload = {
          recipient_email: non_reporter_email_address,
          recipient_user_id: nonReporterUserIds[0], // 最初の未報告者に送信
          notification_deadline_time,
          morning_meeting_start_time,
        };
  
        const response = await fetch('/api/send-email', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(emailPayload),
        });
  
        if (response.ok) {
          emailSent = true;
          emailSendCount = 1;
        }
      } catch {
        emailSent = false;
        emailSendCount = 0;
      }
    }
  
    return {
      prompt_target_user_count: promptTargetCount,
      prompt_target_user_ids: nonReporterUserIds,
      notification_email_sent: emailSent,
      notification_email_send_count: emailSendCount,
    };
  }
  return { sendPromptNotificationEmailsForNonReporters };
})();
export const sendPromptNotificationEmailsForNonReporters = __aivicBundle_175_sendPromptNotificationEmailsForNonReporters.sendPromptNotificationEmailsForNonReporters;
/* AIVIC_FUNCTION_BUNDLE_END owner=sendPromptNotificationEmailsForNonReporters */

/* AIVIC_FUNCTION_BUNDLE_START owner=sendUnreportedMemberNotification exports=sendUnreportedMemberNotification */
const __aivicBundle_176_sendUnreportedMemberNotification = (() => {
  interface SendUnreportedMemberNotificationInput {
    unreported_members: Array<{
      user_id: string;
      user_name: string;
      department_id: string;
    }>;
    department_head_email: string;
    morning_meeting_start_time: Date;
    current_time: Date;
  }
  
  interface SendUnreportedMemberNotificationResult {
    message_body: string;
    recipient_email: string;
    notification_sent: boolean;
  }
  
  function sendUnreportedMemberNotification(
    input: SendUnreportedMemberNotificationInput
  ): SendUnreportedMemberNotificationResult {
    const {
      unreported_members,
      department_head_email,
      morning_meeting_start_time,
      current_time,
    } = input;
  
    const memberNames = unreported_members.map((member) => member.user_name);
  
    const minutesUntilMeeting = Math.floor(
      (morning_meeting_start_time.getTime() - current_time.getTime()) / 60000
    );
  
    const urgencyLevel =
      minutesUntilMeeting <= 5
        ? "緊急"
        : minutesUntilMeeting <= 15
          ? "重要"
          : "通常";
  
    const memberList = memberNames.join("、");
  
    const message_body = `以下の${memberNames.length}名から朝会報告がまだ提出されていません。\n\n【未報告者】\n${memberList}\n\n【催促レベル】${urgencyLevel}\n【朝会開始時刻まで】${minutesUntilMeeting}分\n\nお手数ですが、上記メンバーへの報告提出を促していただきますようお願いいたします。`;
  
    // notification_sent is true when message is generated and all required fields are valid
    const notification_sent = Boolean(
      message_body && 
      department_head_email && 
      memberNames.length > 0
    );
  
    return {
      message_body,
      recipient_email: department_head_email,
      notification_sent,
    };
  }
  return { sendUnreportedMemberNotification };
})();
export const sendUnreportedMemberNotification = __aivicBundle_176_sendUnreportedMemberNotification.sendUnreportedMemberNotification;
/* AIVIC_FUNCTION_BUNDLE_END owner=sendUnreportedMemberNotification */

/* AIVIC_FUNCTION_BUNDLE_START owner=sendReportMissingReminderNotification exports=sendReportMissingReminderNotification */
const __aivicBundle_177_sendReportMissingReminderNotification = (() => {
  async function sendReportMissingReminderNotification(
    non_reported_members: Array<{
      user_id: string;
      member_name: string;
      email: string;
    }>,
    department_head_email: string
  ): Promise<{ success: boolean; message: string }> {
    // 重複を除外して一意な部員を抽出
    const uniqueMembers = Array.from(
      new Map(
        non_reported_members.map((member) => [member.user_id, member])
      ).values()
    );
  
    // 一意な部員名をカンマ区切りで結合
    const memberNameList = uniqueMembers
      .map((member) => member.member_name)
      .join('、');
  
    // メール本文を構築
    const emailSubject = '未報告部員への通知';
    const emailBody = `以下の部員から報告がありません：${memberNameList}`;
  
    // fetch を使用してメール送信
    const response = await fetch('/api/send-email', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        to: department_head_email,
        subject: emailSubject,
        body: emailBody,
      }),
    });
  
    const result = await response.json();
    return result;
  }
  return { sendReportMissingReminderNotification };
})();
export const sendReportMissingReminderNotification = __aivicBundle_177_sendReportMissingReminderNotification.sendReportMissingReminderNotification;
/* AIVIC_FUNCTION_BUNDLE_END owner=sendReportMissingReminderNotification */
